head.script:
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var url = "popup_modal_modaless_WPFF-286_(WSQ-3669)_sub1.xml";
    var options = {};
    options.id = "aaaaa1";
    options.type = "litewindow";
    options.width = "200px";
    options.height = "300px";
    options.modal = "false";
    options.frameMode = "wframe";
    WebSquare.util.openPopup(url, options);
    WebSquare.wUnit.getJq("#aaaaa1").css("z-index", "6011");
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.popupID = $w.getParameter("popupID");
    console.log("popupID : " + popupID);
    //var parentobj = opener || parent;
    //console.log("parentobj : " + parentobj);
    //console.log("parentfn : " + parentobj.scwin.parentfn());
    // parentobj.scwin.parentfn();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
